VALUES (228066, 'tt1976009', NULL, 'Victor Frankenstein', 'Victor Frankenstein', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/bYUmSLPtWylFKbEBHOXT1kt9l5b.jpg', 'https://image.tmdb.org/t/p/original/byMyHJvhiIMKEYqO4I3UhIPEm7G.jpg', 'While searching for animal body parts at a London circus, radical scientist Victor Frankenstein meets gifted surgeon Igor Strausman. Not only does the brilliant doctor offer Strausman his friendship, but also a chance to work with him on groundbreaking research that could change the world forever. When Victor''s experiments with life and death go too far, only Igor can bring him back from the brink of madness and save him from his monstrous creation.', NULL, NULL, 2.4797, 6.0, 0, 11.085, '2026-11-19 03:47:19', '2026-11-19 03:47:19')
