VALUES (454, 'tt0117509', NULL, 'Romeo + Juliet', 'Romeo + Juliet', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/dJCDUkXhfRdc4q8e4VCKEBbqzBT.jpg', 'https://image.tmdb.org/t/p/original/hoQBa4EK6KFS31sPBND9zMjARfb.jpg', 'In this contemporary take on William Shakespeare''s classic tragedy, the Montagues and Capulets have moved their ongoing feud to the sweltering suburb of Verona Beach, where Romeo and Juliet fall in love and secretly wed. Though the film is visually modern, the bard''s dialogue remains.', NULL, NULL, 7.6861, 6.775, 0, 5.71847169811320767e+01, '2026-07-15 12:01:52', '2026-11-19 03:47:19')
