VALUES (9479, 'tt0107688', NULL, 'The Nightmare Before Christmas', 'The Nightmare Before Christmas', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'https://image.tmdb.org/t/p/original/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly Pumpkin King of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning in his place. But, as the holiday approaches, Jack''s rag-doll girlfriend Sally tries to foil his well-meaning yet misguided plans.', NULL, NULL, 88.9484, 7.86, 0, 3.03158333333333338e+01, '2026-07-15 12:01:52', '2026-11-19 03:47:19')
