VALUES (13885, 'tt0408236', NULL, 'Sweeney Todd: The Demon Barber of Fleet Street', 'Sweeney Todd: The Demon Barber of Fleet Street', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/gAW4J1bkRjZKmFsJsIiOBASeoAp.jpg', 'https://image.tmdb.org/t/p/original/obYVvi6eD4rjFeC7g4uoZQPIh7F.jpg', 'The infamous story of Benjamin Barker, a.k.a Sweeney Todd, who sets up a barber shop down in London which is the basis for a sinister partnership with his fellow tenant, Mrs. Lovett. Based on the hit Broadway musical.', NULL, NULL, 6.8041, 7.173, 0, 2.80308333333333337e+01, '2026-07-15 12:01:52', '2026-11-19 03:47:19')
