VALUES (617126, 'tt10676052', NULL, 'The Fantastic 4: First Steps', 'The Fantastic 4: First Steps', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/nf5qaSEvyYSNeFH0YhSs5EsBLX9.jpg', 'https://image.tmdb.org/t/p/original/s94NjfKkcSczZ1FembwmQZwsuwY.jpg', 'Against the vibrant backdrop of a 1960s-inspired, retro-futuristic world, Marvel''s First Family is forced to balance their roles as heroes with the strength of their family bond, while defending Earth from a ravenous space god called Galactus and his enigmatic Herald, Silver Surfer.', NULL, NULL, 26.0506, 6.927, 0, 1.43057142857142842e+01, '2026-07-15 12:01:52', '2026-11-19 03:47:19')
