VALUES (9655, 'tt0454945', NULL, 'She''s the Man', 'She''s the Man', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/8exPgs8jLGh26BGSrAyHa9MeFyO.jpg', 'https://image.tmdb.org/t/p/original/9ys3pySjmZiONZWAy8QhOxv5SDH.jpg', 'Viola Hastings is in a real jam. Complications threaten her scheme to pose as her twin brother, Sebastian, and take his place at a new boarding school. She falls in love with her handsome roommate, Duke, who loves beautiful Olivia, who has fallen for Sebastian! As if that were not enough, Viola''s twin returns from London ahead of schedule but has no idea that his sister has already replaced him on campus.', NULL, NULL, 5.7964, 6.8, 0, 1.19433333333333333e+01, '2026-07-31 03:33:23', '2026-11-19 03:47:19')
