VALUES (229, 'tt0026138', NULL, 'Bride of Frankenstein', 'Bride of Frankenstein', 'movie', 1935, 'https://image.tmdb.org/t/p/w500/5241zUwe7rC17MNc2QpCBKKdp1N.jpg', 'https://image.tmdb.org/t/p/original/hrED8MSOn4xJP9Cpk7WomUcFKGI.jpg', 'After recovering from injuries sustained in the mob attack upon himself and his creation, Dr. Henry Frankenstein falls under control of his former mentor, Dr. Pretorius, who insists the now-chastened doctor resume his experiments in creating new life. Meanwhile, the Monster remains on the run from those who wish to destroy him.', NULL, NULL, 2.8488, 7.5, 0, 6.04666666666666685e+00, '2026-08-08 02:23:49', '2026-11-19 03:47:19')
