VALUES (22726, 'tt0054950', NULL, 'Battle of the Worlds', 'Il pianeta degli uomini spenti', 'movie', 1961, 'https://image.tmdb.org/t/p/w500/pB0PFki9xYEg0xnPCczT7wjQOTT.jpg', 'https://image.tmdb.org/t/p/original/6TLDBIHpFNNOfItGsSqLLcyMLWJ.jpg', 'A stray planet on a collision course with Earth instead takes orbit around our blue marble. What seems like a dead planet suddenly launches a fleet of flying saucers which attack our space fleets.', NULL, NULL, 0.8566, 4.6, 0, 11.035, '2026-08-12 02:31:31', '2026-11-19 03:47:19')
