VALUES (34276, 'tt0058100', NULL, 'First Men in the Moon', 'First Men in the Moon', 'movie', 1964, 'https://image.tmdb.org/t/p/w500/q2Ee1fUretsxTvNrobQzeVYbq22.jpg', 'https://image.tmdb.org/t/p/original/ispyRJVbcB3c9y6AhuZdbgMuzi.jpg', 'The world is delighted when a spacecraft containing a crew comprised of the world''s astronauts lands on the moon, but are shocked when the astronauts discover an old British flag and a document declaring that the moon is taken for Queen Victoria, proving that the astronauts were not the first men on the moon.', NULL, NULL, 1.8958, 6.319, 0, 11.035, '2026-08-12 02:31:31', '2026-11-19 03:47:19')
