VALUES (21538, 'tt0243759', NULL, 'The American Astronaut', 'The American Astronaut', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/qeh8Rzyr7VJaZWep7Vi5MP1e5hG.jpg', 'https://image.tmdb.org/t/p/original/bUa4SvSt35pwvJJquRWUvIPS1UQ.jpg', 'Samual Curtis''s first mission in this bizarre science fiction musical comedy requires him to take a cat to a saloon on an asteroid. There, he meets his former dance partner (the Blueberry Pirate) and collects his payment: a device capable of producing a Real Live Girl. Including music by alternative rock group The Billy Nayer Show, this film began life as a live show with a loyal following.', NULL, NULL, 1.2233, 6.797, 0, 8.18666666666666564e+00, '2026-08-24 01:47:08', '2026-11-19 03:47:19')
